UPDATE tb_company_employee SET
  dept_name  = #{dept_name},
  emp_name   = #{emp_name},
  title_name = #{title_name},
  mobile_no  = #{mobile_no},
  id         = #{id},
  direct_no  = #{direct_no}
  , pw_no = #{pw_no}
WHERE emp_id = #{emp_id}

UPDATE tb_company_employee
SET use_yn = CASE WHEN use_yn='Y' THEN 'N' ELSE 'Y' END
WHERE emp_id = #{emp_id}
